 """Conversational helper with offline fallbacks and a streaming tool loop.

 The loop fans the MCP tools and two local tools into the completion:

 * ``render_ui`` is intercepted and validated against the client's catalog.
 * ``remember`` is intercepted and written to local Studio memory as a proposal.

 The agent speaks to the PM's ambition first. ODI structures are translated
 underneath; they are never the greeting.
 """

 from __future__ import annotations

 import json
 import logging
 from collections.abc import AsyncIterator
 from typing import Any

 from fastmcp import Client as McpClient
 from openai import AsyncOpenAI

 from agentic_odi_studio_api.studio.memory import OBSERVATION_KINDS, StudioMemory
 from agentic_odi_studio_api.studio.offline_ui import offline_reply
 from agentic_odi_studio_api.studio.probes import check_llm_health
 from agentic_odi_studio_api.studio.schemas import ChatRequest
 from agentic_odi_studio_api.studio.ui_spec import RENDER_UI_TOOL, UiCatalog

 logger = logging.getLogger(__name__)

 REMEMBER_TOOL = "remember"

 SYSTEM_PROMPT = """You are the PM's strategist in The Living Studio. Your job is to help them choose and win the next opportunity that matters — to their customers, the business, and their career.

 The PM's ambition is the center. Understanding the business and deciding what to build are evidence for the opportunity, not the opening question. You are warm, direct, and honest. You are not an ODI tutor.

 How to begin
 - Start with the opportunity they want to chase, or the win they want to be known for.
 - Ask one question at a time. Do not interview them with a list.
 - If they have a mandate, help them turn it into an opportunity they can own.
 - If they do not know what to chase, use the discovery path: what is changing, where the workaround is ugly, and what they could uniquely own. Offer three concrete hypotheses, each with why now and why them.
 - Learn about the PM as a person: role, scope, strengths, what they want to be known for, risk appetite, and time horizon.

 Translate, don't teach
 - Translate their words into rigorous structures silently.
 - Use "job", "outcome", "opportunity score", "job map", or "ODI" only if the PM uses them first.
 - When you show a surface, use plain language: "the work your customer is trying to get done", "what good looks like", "where the need is underserved", "what changes if we do this".
 - Keep the Opportunity Thesis as the default surface once you have enough: the opportunity, the outcome, the business case, the career case, what needs to be true, and the next proof.

 Reflect before advising
 - Before recommendations, say what you heard: "Here's the opportunity I hear..." Then name what you are unsure about and invite correction.
 - Never flatter. Challenge with care: "Is this a real opportunity, or a visible project?" "Will this still matter in two years?"

 Memory
 - When you learn a durable fact about the PM, their business, their stakeholders, a constraint, or the opportunity, call `remember` once. Kinds: career, opportunity, business, stakeholder, constraint, evidence, preference.
 - Do not say "I'll remember that" in prose. Do not ask permission to remember. The PM can edit or dismiss it in What I've learned.
 - Do not invent evidence, quotes, or numbers. Label assumptions.

 Surfaces
 - When a surface carries the evidence better than a paragraph, call `render_ui` once, then write one short sentence.
 - Never describe in prose what a card can already show.

 Voice
 - Warm, encouraging, humble, and thankful. Short paragraphs. No emojis. No corporate jargon. No therapy-speak.
 - Thank the PM for specifics. Admit uncertainty. Leave them with one clear next step."""


 def _sse(event: str, data: dict[str, Any]) -> str:
     return f"event: {event}\ndata: {json.dumps(data)}\n\n"


 def _memory_context(memory: StudioMemory | None) -> str:
     if memory is None:
         return ""
     try:
         return memory.context_block()
     except Exception:  # noqa: BLE001
         logger.exception("Could not read Studio memory context")
         return ""


 def _to_openai_messages(
     request: ChatRequest, memory: StudioMemory | None = None
 ) -> list[dict[str, Any]]:
     system = SYSTEM_PROMPT
     context = _memory_context(memory)
     if context:
         system = f"{system}\n\n{context}"
     messages: list[dict[str, Any]] = [{"role": "system", "content": system}]
     for message in request.messages:
         messages.append({"role": message.role, "content": message.content})
     return messages


 def _openai_tools(mcp_tools: list[Any]) -> list[dict[str, Any]]:
     return [
         {
             "type": "function",
             "function": {
                 "name": tool.name,
                 "description": tool.description,
                 "parameters": tool.input_schema,
             },
         }
         for tool in mcp_tools
     ]


 def _render_ui_tool(catalog: UiCatalog) -> dict[str, Any]:
     return {
         "type": "function",
         "function": {
             "name": RENDER_UI_TOOL,
             "description": (
                 "Render one rich surface inline in the conversation. Reach for this whenever a "
                 "surface carries the evidence better than a paragraph: the opportunity thesis, "
                 "a ranked opportunity board, a before/after simulation of a bet, a customer "
                 "quote, the work map, or a decision record. Send one surface, then one short "
                 "sentence.\n\n"
                 "Catalog (* marks a required prop):\n" + catalog.describe()
             ),
             "parameters": catalog.tool_schema(),
         },
     }


 def _remember_tool() -> dict[str, Any]:
     return {
         "type": "function",
         "function": {
             "name": REMEMBER_TOOL,
             "description": (
                 "Save a durable fact about the PM, their business, their stakeholders, a "
                 "constraint, a piece of evidence, or the opportunity so you do not have to ask "
                 "again. The PM can edit or dismiss it in What I've learned. Call this once per "
                 "new fact. Do not narrate it."
             ),
             "parameters": {
                 "type": "object",
                 "properties": {
                     "kind": {"type": "string", "enum": list(OBSERVATION_KINDS)},
                     "text": {
                         "type": "string",
                         "description": "One short, concrete sentence in the PM's language.",
                     },
                     "data": {
                         "type": "object",
                         "description": "Optional structured facts for the thesis or the UI.",
                     },
                     "confidence": {"type": "number", "minimum": 0, "maximum": 1},
                 },
                 "required": ["kind", "text"],
             },
         },
     }


-def _local_tools(
-    catalog: UiCatalog | None, memory: StudioMemory | None
-) -> list[dict[str, Any]]:
+def _local_tools(catalog: UiCatalog | None, memory: StudioMemory | None) -> list[dict[str, Any]]:
     tools: list[dict[str, Any]] = []
     if catalog is not None:
         tools.append(_render_ui_tool(catalog))
     if memory is not None:
         tools.append(_remember_tool())
     return tools


 def _persist_turn(
     memory: StudioMemory | None,
     conversation_id: str | None,
     role: str,
     content: str,
     parts: list[dict[str, Any]],
 ) -> None:
     if memory is None or conversation_id is None:
         return
     try:
         memory.append_turn(conversation_id, role, content, parts)
     except Exception:  # noqa: BLE001
         logger.exception("Could not persist a Studio conversation turn")


 def _text_parts(text: str) -> list[dict[str, Any]]:
     return [{"kind": "text", "text": text}] if text else []


 async def stream_chat(
     request: ChatRequest, memory: StudioMemory | None = None
 ) -> AsyncIterator[str]:
     """Yield SSE frames: conversation, status, delta, tool, ui, memory, message, canvas_dirty, error."""
     last_user = next((m.content for m in reversed(request.messages) if m.role == "user"), "")

     conversation_id: str | None = None
     user_turn_id: int | None = None
     if memory is not None:
         try:
             conversation_id = memory.ensure_conversation(request.conversation_id)
             yield _sse("conversation", {"id": conversation_id})
             if last_user:
                 user_turn_id = memory.append_turn(conversation_id, "user", last_user)
         except Exception:  # noqa: BLE001
             logger.exception("Could not open Studio memory for this conversation")
             conversation_id = None

     yield _sse("status", {"phase": "health_check"})
     healthy, _message = await check_llm_health(request.base_url, request.api_key, request.model)

     if not healthy:
         reply, surfaces = offline_reply(last_user)
         parts: list[dict[str, Any]] = _text_parts(reply)
         parts.extend(
             {"kind": "ui", "id": f"offline-{index}", "spec": spec}
             for index, spec in enumerate(surfaces)
         )
         _persist_turn(memory, conversation_id, "assistant", reply, parts)
         yield _sse("delta", {"text": reply})
         for index, spec in enumerate(surfaces):
             yield _sse("ui", {"id": f"offline-{index}", "spec": spec})
         yield _sse("message", {"content": reply})
         return

     catalog = UiCatalog.from_manifest(
         request.ui_catalog.model_dump() if request.ui_catalog else None
     )

     yield _sse("status", {"phase": "mcp_tools"})
     llm_client = AsyncOpenAI(base_url=request.base_url, api_key=request.api_key, timeout=15.0)

     async with McpClient(request.mcp_url) as mcp_client:
         mcp_tools = await mcp_client.list_tools()
         openai_tools = _openai_tools(mcp_tools) + _local_tools(catalog, memory)
         messages: list[Any] = _to_openai_messages(request, memory)

         yield _sse("status", {"phase": "model"})
         stream: Any = await llm_client.chat.completions.create(  # type: ignore[call-overload]
             model=request.model,
             messages=messages,
             tools=openai_tools if openai_tools else None,
             tool_choice="auto" if openai_tools else None,
             stream=True,
         )

         buffered_text: list[str] = []
         tool_calls: dict[int, dict[str, str]] = {}

         async for chunk in stream:
             delta = chunk.choices[0].delta
             if delta.content:
                 if not tool_calls:
                     # Prose renders as it is generated. If a tool call turns up
                     # in a later chunk we retract it below, so nothing the model
                     # did not mean to say survives.
                     yield _sse("delta", {"text": delta.content})
                 buffered_text.append(delta.content)
             for tool_call in delta.tool_calls or []:
                 entry = tool_calls.setdefault(
                     tool_call.index, {"id": "", "name": "", "arguments": ""}
                 )
                 if tool_call.id:
                     entry["id"] = tool_call.id
                 if tool_call.function is not None:
                     if tool_call.function.name:
                         entry["name"] = tool_call.function.name
                     if tool_call.function.arguments:
                         entry["arguments"] += tool_call.function.arguments

         if not tool_calls:
             content = "".join(buffered_text)
             _persist_turn(memory, conversation_id, "assistant", content, _text_parts(content))
             yield _sse("message", {"content": content})
             return

         if buffered_text:
             # Retract the partial prose: the model chose to call a tool instead.
             yield _sse("message", {"content": ""})

         messages.append(
             {
                 "role": "assistant",
                 "content": None,
                 "tool_calls": [
                     {
                         "id": entry["id"],
                         "type": "function",
                         "function": {
                             "name": entry["name"],
                             "arguments": entry["arguments"] or "{}",
                         },
                     }
                     for entry in tool_calls.values()
                 ],
             }
         )

         ui_count = 0
         ui_parts: list[dict[str, Any]] = []
         canvas_dirty = False

         for entry in tool_calls.values():
             name = entry["name"]
             yield _sse("tool", {"name": name, "status": "start"})
             try:
                 arguments = json.loads(entry["arguments"] or "{}")
             except json.JSONDecodeError:
                 arguments = {}
             if not isinstance(arguments, dict):
                 arguments = {}

             if name == RENDER_UI_TOOL:
                 if catalog is None:
                     result_str = "UI is not available to this client. Answer in prose instead."
                     yield _sse("tool", {"name": name, "status": "error", "preview": result_str})
                 else:
                     problem = catalog.validate(arguments)
                     if problem:
                         result_str = (
                             f"UI rejected: {problem}. Nothing was shown to the user. "
                             "Fix it and try once more."
                         )
                         yield _sse("tool", {"name": name, "status": "error", "preview": problem})
                     else:
                         ui_count += 1
                         surface_id = f"ui-{ui_count}"
                         result_str = "Rendered inline for the user."
                         ui_parts.append({"kind": "ui", "id": surface_id, "spec": arguments})
                         yield _sse("tool", {"name": name, "status": "ok"})
                         yield _sse("ui", {"id": surface_id, "spec": arguments})
             elif name == REMEMBER_TOOL:
                 if memory is None:
                     result_str = "Memory is not available to this client."
                     yield _sse("tool", {"name": name, "status": "error", "preview": result_str})
                 else:
                     confidence = arguments.get("confidence")
                     if isinstance(confidence, bool) or not isinstance(confidence, (int, float)):
                         confidence = None
                     data = arguments.get("data")
                     try:
                         observation = memory.add_observation(
                             kind=str(arguments.get("kind", "")),
                             text=str(arguments.get("text", "")),
                             data=data if isinstance(data, dict) else {},
                             confidence=float(confidence) if confidence is not None else None,
                             source_turn=user_turn_id,
                         )
                     except (TypeError, ValueError) as exc:
                         result_str = f"Not saved: {exc}"
                         yield _sse(
                             "tool",
                             {"name": name, "status": "error", "preview": result_str},
                         )
                     else:
                         result_str = "Noted. The PM can review it in What I've learned."
                         yield _sse("tool", {"name": name, "status": "ok"})
                         yield _sse("memory", {"observation": observation})
             else:
                 try:
                     result = await mcp_client.call_tool(name, arguments)
                     result_str = str(result)
                     canvas_dirty = True
                     yield _sse("tool", {"name": name, "status": "ok", "preview": result_str[:280]})
                 except Exception as exc:  # noqa: BLE001
                     result_str = f"Error calling {name}: {exc}"
                     yield _sse("tool", {"name": name, "status": "error", "preview": result_str})

             messages.append(
                 {
                     "role": "tool",
                     "tool_call_id": entry["id"],
                     "name": name,
                     "content": result_str,
                 }
             )

         if canvas_dirty:
             yield _sse("canvas_dirty", {"value": True})

         final_stream: Any = await llm_client.chat.completions.create(
             model=request.model,
             messages=messages,
             stream=True,
         )
         final_parts: list[str] = []
         async for chunk in final_stream:
             delta = chunk.choices[0].delta
             if delta.content:
                 final_parts.append(delta.content)
                 yield _sse("delta", {"text": delta.content})

         final_content = "".join(final_parts)
         stored_parts = list(ui_parts) + _text_parts(final_content)
         _persist_turn(memory, conversation_id, "assistant", final_content, stored_parts)
         yield _sse("message", {"content": final_content})


 __all__ = ["REMEMBER_TOOL", "SYSTEM_PROMPT", "stream_chat"]

